package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SettingLog;
import net.officefloor.hq.app.sheet.SettingLogRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Sets the settings the form sets: a setting that carries a figure (the clerk limit, floor, terms, late percent,
 *  each grade's own terms, cap, proof threshold, note threshold, each grade's grace days, each grade's proof threshold, review threshold) is recorded from its from-date (the sheet's today when none is given), replacing a
 *  value recorded from that date and keeping the others; the policy date, period numbering from and entry date are set; a permission matrix entry
 *  (key perm-<action>), the grace days, the pot, the parent sheet, the fiscal year start month and the alert threshold and the escalation gap and the review SLA and the proof kinds and the default grade are recorded undated. Each is logged with the sheet's today (so the
 *  settings can be worked out as they stood on an earlier date). */
public class ApplySettings {
    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository, SettingLogRepository log) {
        for (SettingsInput.Change change : input.changes()) {
            LocalDate from = null;
            if (change.dated()) {
                from = change.from() != null ? change.from() : sheet.getToday();
                sheet.record(change.key(), from, change.value());
            } else if (change.key().startsWith("perm-") || Sheet.GRACE_DAYS.equals(change.key())
                    || Sheet.ESCALATE_AFTER.equals(change.key()) || Sheet.REVIEW_SLA.equals(change.key())
                    || Sheet.PROOF_KINDS.equals(change.key()) || Sheet.DEFAULT_GRADE.equals(change.key())
                    || Sheet.POT.equals(change.key()) || Sheet.PARENT.equals(change.key())
                    || Sheet.FISCAL_START_MONTH.equals(change.key())
                    || Sheet.ALERT_THRESHOLD.equals(change.key())) {
                sheet.record(change.key(), null, change.value());
            } else if (Sheet.POLICY_DATE.equals(change.key())) {
                sheet.setPolicyDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(change.key())) {
                sheet.setPeriodNumberingFrom(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.ENTRY_DATE.equals(change.key())) {
                sheet.setEntryDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else {
                continue;
            }
            log.save(new SettingLog(sheet.getId(), change.key(), from, change.value(), sheet.getToday()));
        }
        repository.saveAndFlush(sheet);
        log.flush();
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetSetting;

/** The sheet's settings as the screen shows them, each in force on the sheet's today: the clerk limit with two decimals (null: no limit) and the
 *  floor with two decimals, and the terms in days, and the late percent with two decimals, and the policy date (YYYY-MM-DD; "" when
 *  blank: the sheet's today), and the period numbering from (YYYY-MM-DD; "" when off), and the own terms in days of grades A, B and C
 *  ("" when the grade uses the sheet's terms), and the cap with two decimals ("" when there is none), and the proof threshold with two decimals ("" when there is none); and the values recorded
 *  for each dated setting, by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), by from-date; and the permission matrix
 *  entry of each of open, settle, void, reassign, close and reopen (its comma separated roles; "" when blank: the standing rule); and the grace days ("" when off); and the note threshold with two decimals ("" when there is none); and the entry date (YYYY-MM-DD; "" when off); and the grace days of grades A, B and C in force ("" when none); and the proof thresholds of grades A, B and C in force ("" when none); and the pot with two decimals ("" when there is none; not dated); and the parent sheet's id ("" when none; not dated); and the fiscal year start month (1 to 12; not dated); and the alert threshold with two decimals ("" when off; not dated); and the rounding mode in force (half-up or half-even; "" when none); and the review threshold with two decimals ("" when there is none); and the escalation gap in days ("" when off; not dated); and the review SLA in days ("" when none; not dated); and the proof kinds (comma separated; "" when none; not dated); and the default grade ("" when blank, meaning A; not dated); and the clerk limits of grades A, B and C in force ("" when none). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap, String proofThreshold,
        Map<String, List<Dated>> dated, String permOpen, String permSettle, String permVoid, String permReassign,
        String permClose, String permReopen, String graceDays, String noteThreshold, String entryDate,
        String graceA, String graceB, String graceC,
        String proofThresholdA, String proofThresholdB, String proofThresholdC, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade,
        String clerkLimitA, String clerkLimitB, String clerkLimitC) {

    /** A value recorded from a date on (null from: the beginning of time; null value: blank). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Sheet sheet) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (SheetSetting s : sheet.getSettings()) {
            dated.computeIfAbsent(s.getKey(), k -> new ArrayList<>())
                    .add(new Dated(s.getFromDate() == null ? null : s.getFromDate().toString(), s.getValue()));
        }
        return new SettingsResponse(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                sheet.floorOn(sheet.getToday()).setScale(2).toPlainString(), String.valueOf(sheet.termsOn(sheet.getToday())),
                sheet.latePctOn(sheet.getToday()).setScale(2).toPlainString(),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                gradeTerms(sheet, "A"), gradeTerms(sheet, "B"), gradeTerms(sheet, "C"),
                sheet.getCap() == null ? "" : sheet.getCap().toPlainString(),
                sheet.proofThresholdOn(sheet.getToday()) == null ? "" : sheet.proofThresholdOn(sheet.getToday()).toPlainString(),
                dated, sheet.permOf("open"), sheet.permOf("settle"), sheet.permOf("void"), sheet.permOf("reassign"),
                sheet.permOf("close"), sheet.permOf("reopen"),
                sheet.getGraceDays() == null ? "" : String.valueOf(sheet.getGraceDays()),
                sheet.noteThresholdOn(sheet.getToday()) == null ? "" : sheet.noteThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEntryDate() == null ? "" : sheet.getEntryDate().toString(),
                gradeGrace(sheet, "A"), gradeGrace(sheet, "B"), gradeGrace(sheet, "C"),
                gradeProofThreshold(sheet, "A"), gradeProofThreshold(sheet, "B"), gradeProofThreshold(sheet, "C"),
                sheet.getPot() == null ? "" : sheet.getPot().toPlainString(),
                sheet.getParent() == null ? "" : sheet.getParent(),
                String.valueOf(sheet.getFiscalStartMonth()),
                sheet.getAlertThreshold() == null ? "" : sheet.getAlertThreshold().toPlainString(),
                sheet.roundingOn(sheet.getToday()) == null ? "" : sheet.roundingOn(sheet.getToday()),
